Section SKB.
  Variables (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (x1 x6 x7 x8 x9 x11 x13 x15 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word).
  Variables (m : fmem) (DT SY cons sym1 : Z) (sorted : list (option Z)) (js jt : list byte) (ncells : nat).
  Variable POST : machine_state -> Prop.
  Hypothesis HJT : length jt = (4 * ncells)%nat.
  Hypothesis HJS : length js = length sorted.
  Hypothesis HLS : length sorted = 256%nat.
  Hypothesis HDT : 0 < DT /\ DT + 4 + 4 * Z.of_nat ncells <= 2^47.
  Hypothesis DJ : DT + 4 + 4 * Z.of_nat ncells <= SY \/ SY + 256 <= DT + 4.
  Hypothesis HSY : 0 < SY /\ SY + 256 <= 2^47.
  Hypothesis HCONS : 1 <= cons <= 12.
  Hypothesis HS1 : 0 <= sym1 < 256.
  Notation INV m1 dt := (x2f_inv m m1 DT SY js jt sorted ncells dt).
  Notation D := (cons * 65536 + 16777216).
  Notation UU := (Z.lor (Z.lor D sym1 ≪ 32 mod 18446744073709551616) (Z.lor D sym1)).

  Lemma skB_chunks : forall n c dt1 v vend m1 dtR,
    c = build_x2 sym1 cons 0 1 ->
    store_run (8 * n) dt1 v c = Ok dtR -> 0 <= v -> v + 8 * Z.of_nat n = vend -> (0 < n)%nat -> INV m1 dt1 ->
    (forall m2, INV m2 dtR ->
       evt psegs POST (MS (mkR x1 sp gp tp (Z_to_bv 64 (DT + 20 + 4 * vend)) x6 x7 x8 x9 (Z_to_bv 64 (UU ≫ 48)) x11 (Z_to_bv 64 UU) x13 (Z_to_bv 64 (UU ≫ 32)) x15 (Z_to_bv 64 (UU ≫ 16)) (Z_to_bv 64 (DT + 20 + 4 * vend)) x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
                          F (Z_to_bv 64 0x13f08) fc None m2 (seg_rom psegs))) ->
    evt psegs POST (MS (mkR x1 sp gp tp (Z_to_bv 64 (DT + 20 + 4 * vend)) x6 x7 x8 x9 (Z_to_bv 64 (UU ≫ 48)) x11 (Z_to_bv 64 UU) x13 (Z_to_bv 64 (UU ≫ 32)) x15 (Z_to_bv 64 (UU ≫ 16)) (Z_to_bv 64 (DT + 20 + 4 * v)) x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
                       F (Z_to_bv 64 0x13ec0) fc None m1 (seg_rom psegs)).
